// src/validation/internal-schema.ts
function snapshotSchema(input) {
  const value = JSON.parse(JSON.stringify(input));
  const freeze = (v) => {
    if (v !== null && typeof v === "object") {
      for (const child of Object.values(v))
        freeze(child);
      Object.freeze(v);
    }
  };
  freeze(value);
  return value;
}
